input.newString:
const handleVenueSelect = async (venue: VenueData) => {
  setSelectedVenue(venue);
  console.log('Venue selected:', venue);

  // Save venue selection to database
  if (currentPartyId && currentUser) {
    try {
      const response = await fetch('/api/party-venue', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          partyId: currentPartyId,
          userId: currentUser.id,
          venue,
          isCustom: false
        })
      });

      if (response.ok) {
        console.log('Venue selection saved to database');
      } else {
        console.error('Failed to save venue selection');
      }
    } catch (error) {
      console.error('Error saving venue selection:', error);
    }
  }

  // Update local party data
  if (partyData) {
    const updatedPartyData: PartyData = {
      ...partyData,
      venue: venue
    };

    setPartyData(updatedPartyData);
    console.log('Venue automatically added to party:', venue.name);
  }
};

